function mimeFor(file){const type=String(file.type||"").toLowerCase(),canonical=({"image/jpg":"image/jpeg","image/tif":"image/tiff","image/x-tiff":"image/tiff"})[type]||type;if(MASTER_MIMES.has(canonical))return canonical;const ext=file.name.split(".").pop()?.toLowerCase();return ({jpg:"image/jpeg",jpeg:"image/jpeg",png:"image/png",webp:"image/webp",heic:"image/heic",heif:"image/heif",tif:"image/tiff",tiff:"image/tiff"})[ext]||canonical}
function normalizedFile(file){const type=mimeFor(file);return !type||String(file.type||"").toLowerCase()===type?file:new File([file],file.name,{type,lastModified:file.lastModified})}
function outputText(output,message){if(typeof output==="function")output(message);else if(output)output.textContent=message}
function fileFingerprint(file){return `${file.name}:${Number(file.size)||0}:${Number(file.lastModified)||0}`}
function fileStem(name){return String(name||"").replace(/\.[^.]+$/,"")}
function pairBasename(name){return fileStem(name).toLowerCase().replace(/(?:[\s_-]+(?:master|private|source|original|derivative|public|web))+$/g,"").replace(/[\s_-]+$/g,"")}
function slugify(value){return String(value||"").normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}
function validDateParts(year,month,day){const date=new Date(Date.UTC(Number(year),Number(month)-1,Number(day)));return date.getUTCFullYear()===Number(year)&&date.getUTCMonth()===Number(month)-1&&date.getUTCDate()===Number(day)?date:null}
function dateFromFilename(name){const stem=fileStem(name),match=stem.match(/(?:^|[^0-9])((?:19|20)\d{2})[-_.]?([01]\d)[-_.]?([0-3]\d)(?:[^0-9]|$)/);if(!match)return null;const date=validDateParts(match[1],match[2],match[3]),token=match[0].match(/(?:19|20)\d{2}[-_.]?[01]\d[-_.]?[0-3]\d/)?.[0]||"";return date?{value:`${match[1]}-${match[2]}-${match[3]}`,label:new Intl.DateTimeFormat("en-US",{month:"long",day:"numeric",year:"numeric",timeZone:"UTC"}).format(date),token}:null}
function metadataFromFilename(name){const date=dateFromFilename(name);let stem=fileStem(name).replace(/(?:[\s_-]+(?:master|private|source|original|derivative|public|web))+$/gi,"");if(date)stem=stem.replace(date.token," ");const words=stem.replace(/[_-]+/g," ").replace(/\s+/g," ").trim(),title=(words||"Blackboard fragment").replace(/\b\w/g,letter=>letter.toUpperCase());return {title,slug:slugify(words||"blackboard-fragment"),caption:title,occurredDate:date?.value||"",dateLabel:date?.label||""}}
function acceptsMaster(file){return MASTER_MIMES.has(mimeFor(file))}
function acceptsDerivative(file){return AUTO_DERIVATIVE_MIMES.has(mimeFor(file))}
function needsSuppliedDerivative(file){return !isHeicUpload(file)&&!AUTO_DERIVATIVE_MIMES.has(mimeFor(file))}
function queuedHeicEditProxy(file){const operation=heicEditProxyQueue.then(()=>createHeicEditProxy(file));heicEditProxyQueue=operation.catch(()=>{});return operation}
function stableId(prefix){return `${prefix}-${globalThis.crypto?.randomUUID?.()||`${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`}`}
function createBatchRow(file,sortOrder){return {id:stableId("blackboard-batch"),fingerprint:fileFingerprint(file),basename:pairBasename(file.name),masterFile:file,derivativeFile:null,...metadataFromFilename(file.name),sortOrder,status:"queued",message:"Ready",masterMediaId:"",derivativeMediaId:"",fragmentId:stableId("blackboard-fragment"),activeSessionId:"",abortController:null,previewUrl:"",previewFileFingerprint:"",previewStatus:"Preparing preview…",previewTask:null}}
function planFragmentBatchSelection(existingRows,derivativePool,masterFiles,derivativeFiles,_recordId,max=BATCH_MAX_FRAGMENTS){const rows=[...existingRows],pool=new Map(derivativePool),seen=new Set(rows.map(row=>row.fingerprint)),derivativeFingerprints=new Set([...pool.values()].map(fileFingerprint)),duplicates=[],rejected=[];for(const file of derivativeFiles){if(!acceptsDerivative(file)){rejected.push(`${file.name}: editing source must be JPEG, PNG, or WebP`);continue}const fingerprint=fileFingerprint(file),key=pairBasename(file.name);if(derivativeFingerprints.has(fingerprint)){duplicates.push(file.name);continue}derivativeFingerprints.add(fingerprint);if(!pool.has(key))pool.set(key,file);else rejected.push(`${file.name}: another editing source already uses this basename`)}for(const row of rows)if(!row.derivativeFile&&pool.has(row.basename))row.derivativeFile=pool.get(row.basename);for(const file of masterFiles){if(!acceptsMaster(file)){rejected.push(`${file.name}: unsupported master format`);continue}const fingerprint=fileFingerprint(file);if(seen.has(fingerprint)){duplicates.push(file.name);continue}if(rows.length>=max){rejected.push(`${file.name}: tray limit is ${max}`);continue}seen.add(fingerprint);const row=createBatchRow(file,rows.length+1);row.derivativeFile=pool.get(row.basename)||null;rows.push(row)}rows.forEach((row,index)=>{row.sortOrder=index+1});return {rows,pool,duplicates,rejected}}

async function derivativeFor(file){
  const type=mimeFor(file);if(!["image/jpeg","image/png","image/webp"].includes(type))return null;
  const bitmap=await createImageBitmap(file),scale=Math.min(1,2400/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement("canvas");
  canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext("2d",{alpha:false}).drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();
  const blob=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error("The JPEG derivative could not be generated.")),"image/jpeg",.88));
  return new File([blob],file.name.replace(/\.[^.]+$/,"")+"-public.jpg",{type:"image/jpeg"});
}
async function uploadMaster(file,output,options={}){if(!window.StudioResumableMedia)throw new Error("The resumable uploader is unavailable. Refresh Studio and try again.");return window.StudioResumableMedia.upload(normalizedFile(file),{token:localStorage.getItem(tokenKey)||"",uploadKind:"archive-master",privacy:"internal",publicPresentation:"hidden",signal:options.signal,onSession:session=>{if(options.trackGlobal!==false)activeUpload=session.id;options.onSession?.(session)},onStatus:message=>outputText(output,message),onProgress:progress=>outputText(output,`Private master ${progress.percent}%`)})}
async function uploadMediaFile(file,{alt="",caption="",privacy="internal",presentation="hidden"}={},output){outputText(output,privacy==="public"?"Uploading public derivative…":"Uploading private editing asset…");const form=new FormData();form.append("file",normalizedFile(file));form.append("alt_text",alt);form.append("caption",caption);form.append("privacy",privacy);form.append("public_presentation",presentation);const payload=await api("/api/admin/media",{method:"POST",body:form});return payload.record}
