async function prepareFragmentAssets(masterFile,chosenSource,alt,output){if(!masterFile)throw new Error("Choose a private master image.");let source=chosenSource||null;if(!source&&isHeicUpload(masterFile)){outputText(output,"Decoding HEIC/HEIF edit source locally…");source=await queuedHeicEditProxy(masterFile)}else if(!source){source=await derivativeFor(masterFile)}if(!source)throw new Error("Add a same-basename JPEG, PNG, or WebP editing source for this TIFF master.");const master=await uploadMaster(masterFile,output);activeUpload="";const editSource=await uploadFragmentEditSource(source,alt,output);return {master,editSource}}

