function batchRowActive(row){return ["starting","uploading-master","preparing-derivative","uploading-derivative","creating"].includes(row.status)}
function batchRowRemovable(row){return fragmentBatchRunning===0&&!batchRowActive(row)&&(row.status==="complete"||(!row.activeSessionId&&!row.masterMediaId&&!row.derivativeAttempted&&!row.derivativeMediaId&&!row.createAttempted))}
function batchDerivativeLabel(row){if(row.derivativeFile)return row.derivativeFile.name;if(needsSuppliedDerivative(row.masterFile))return "Matching JPEG/PNG/WebP editing source required";if(isHeicUpload(row.masterFile))return "Automatic local HEIC/HEIF edit proxy";return "Automatic private editing source"}
function batchPreviewFile(row){return row.derivativeFile||row.generatedDerivativeFile||(AUTO_DERIVATIVE_MIMES.has(mimeFor(row.masterFile))?row.masterFile:null)}
function releaseBatchPreview(row){if(row?.previewUrl)URL.revokeObjectURL(row.previewUrl);if(row){row.previewUrl="";row.previewFileFingerprint=""}}
function batchPreviewMarkup(row){if(row.previewUrl)return `<figure class="bb-batch-row-preview"><img src="${esc(row.previewUrl)}" alt="Preview of ${esc(row.masterFile.name)}"><figcaption>${esc(row.previewStatus||"Preview ready.")}</figcaption></figure>`;return `<div class="bb-batch-row-preview is-pending" aria-live="polite"><strong>${esc(row.previewStatus||"Preparing preview…")}</strong><span>${esc(needsSuppliedDerivative(row.masterFile)?"Add its matching editing source to see this TIFF.":"The preview stays private in this browser until you upload.")}</span></div>`}
async function prepareBatchPreview(row){const source=batchPreviewFile(row);if(source){const fingerprint=fileFingerprint(source);if(row.previewFileFingerprint!==fingerprint){releaseBatchPreview(row);row.previewUrl=URL.createObjectURL(source);row.previewFileFingerprint=fingerprint}row.previewStatus="Preview ready.";return}if(!isHeicUpload(row.masterFile)){row.previewStatus="Preview needs a matching editing source.";return}if(row.previewTask)return row.previewTask;row.previewStatus="Preparing HEIC/HEIF preview…";renderFragmentBatchTray();row.previewTask=queuedHeicEditProxy(row.masterFile).then(async file=>{row.generatedDerivativeFile=file;row.previewTask=null;await prepareBatchPreview(row);renderFragmentBatchTray()}).catch(error=>{row.previewTask=null;row.previewStatus=`Preview unavailable: ${error.message||"HEIC conversion failed."}`;renderFragmentBatchTray()});return row.previewTask}
