async function paint(options={}){if(!options.discardFragmentChanges&&!confirmFragmentViewExit())return false;releaseFragmentViews();const fragment=activeFragment(),record=selected();host.innerHTML=fragment?fragmentWorkflowMarkup(fragment):record?workspaceMarkup(record):libraryView==="fragments"?fragmentLibraryMarkup():libraryMarkup();await hydrateAdminImages();if(fragment&&fragmentWorkflowStep==="edit")await mountActiveEditor(fragment);if(fragment&&fragmentWorkflowStep==="map"){await mountActiveMapper(fragment);const mount=host.querySelector("[data-origin-thread-mount]");if(mount&&window.OriginThreadManager){mount.dataset.mounted="1";window.OriginThreadManager.mount(mount,{entityId:fragment.id})}}return true}

async function reload(options={}){const payload=await api(endpoint("/records"));records=payload.records||[];if(selectedId&&!records.some(item=>item.id===selectedId))selectedId="";await loadFragmentLibrary();if(activeFragmentId&&!fragmentLibrary.some(item=>item.id===activeFragmentId)){activeFragmentId="";activeFragmentEditId=""}await paint(options)}
function formBody(form){const data=new FormData(form),body={};for(const [key,value] of data)if(!(value instanceof File))body[key]=key==="public_visible"?true:value;if(form.elements.public_visible)body.public_visible=form.elements.public_visible.checked;return body}
function iso(value){return value?new Date(value).toISOString():null}
function batchIso(value){return value?new Date(`${value}T12:00:00Z`).toISOString():null}
function batchRowByElement(element){const card=element.closest("[data-fragment-batch-row]");return card?fragmentBatchRows.find(row=>row.id===card.dataset.fragmentBatchRow):null}
function updateBatchRow(row,status,message){if(status)row.status=status;if(message!==undefined)row.message=message;renderFragmentBatchTray()}
function updateBatchProgress(row,message){row.message=message;const card=host?.querySelector(`[data-fragment-batch-row="${CSS.escape(row.id)}"]`),output=card?.querySelector("[data-batch-row-status]");if(output)output.textContent=message}
function validateBatchRow(row){if(!row.title.trim())throw new Error("Add a fragment title.");if(!slugify(row.slug))throw new Error("Add a fragment slug.");if(needsSuppliedDerivative(row.masterFile)&&!row.derivativeFile&&!row.derivativeMediaId)throw new Error("Add a matching JPEG, PNG, or WebP editing source for this TIFF master.")}
function batchSortOrder(row){const batchIds=new Set(fragmentBatchRows.map(item=>item.fragmentId)),existing=Math.max(0,...fragmentLibrary.filter(fragment=>!batchIds.has(fragment.id)).map(fragment=>Number(fragment.sort_order)||0));return existing+row.sortOrder}
