async function createBatchFragment(row){const body={id:row.fragmentId,master_media_id:row.masterMediaId,edit_source_media_id:row.derivativeMediaId,title:row.title.trim(),slug:slugify(row.slug),caption:row.caption.trim(),body:"",occurred_at:batchIso(row.occurredDate),date_precision:row.occurredDate?"day":"undated",date_label:row.dateLabel.trim(),sort_order:batchSortOrder(row),state:"draft",public_visible:false};if(row.createAttempted){const existing=await confirmBatchFragment(row);if(existing)return existing}row.createAttempted=true;try{const payload=await fragmentRequests.create(body);return payload.record}catch(error){const existing=await confirmBatchFragment(row);if(existing)return existing;throw error}}
async function recoverCompletedMaster(row){if(!row.activeSessionId)return null;try{const payload=await api(`/api/admin/media/uploads/${encodeURIComponent(row.activeSessionId)}`),upload=payload.upload;if(upload?.state!=="completed"||!upload.mediaId)return null;const media=await api(`/api/admin/media/${encodeURIComponent(upload.mediaId)}`);return media.record||null}catch{return null}}
async function uploadBatchMaster(row){let master=await recoverCompletedMaster(row);if(!master){try{master=await uploadMaster(row.masterFile,message=>updateBatchProgress(row,message),{signal:row.abortController.signal,trackGlobal:false,onSession:session=>{row.activeSessionId=session.id}})}catch(error){master=await recoverCompletedMaster(row);if(!master)throw error}}row.masterMediaId=master.id;row.activeSessionId="";return master}
function derivativeMatches(record,file,alt){return record?.state==="active"&&record.privacy==="internal"&&record.public_presentation==="hidden"&&record.original_filename===file.name&&Number(record.byte_size)===Number(file.size)&&record.mime_type===mimeFor(file)&&record.alt_text===alt}
async function initialBatchMediaSnapshot(){if(!fragmentBatchMediaSnapshotPromise)fragmentBatchMediaSnapshotPromise=api("/api/admin/media").then(payload=>payload.records||[]).catch(error=>{fragmentBatchMediaSnapshotPromise=null;throw error});return fragmentBatchMediaSnapshotPromise}
async function recoverBatchDerivative(row,file){if(!row.derivativeAttempted||!row.derivativePriorMediaIds)return null;try{const payload=await api("/api/admin/media"),record=(payload.records||[]).find(item=>derivativeMatches(item,file,row.derivativeAltText)&&!row.derivativePriorMediaIds.has(item.id));if(record){fragmentBatchKnownMediaIds.add(record.id);fragmentBatchDerivativeMediaIds.set(fileFingerprint(file),record.id)}return record||null}catch{return null}}
async function uploadBatchDerivative(row,file){const fingerprint=fileFingerprint(file),knownId=fragmentBatchDerivativeMediaIds.get(fingerprint);if(knownId){row.derivativeMediaId=knownId;return {id:knownId}}const pending=fragmentBatchDerivativeUploads.get(fingerprint);if(pending){const shared=await pending;row.derivativeMediaId=shared.id;return shared}const operation=(async()=>{let recovered=await recoverBatchDerivative(row,file);if(recovered)return recovered;if(!row.derivativePriorMediaIds){const snapshot=await initialBatchMediaSnapshot();row.derivativePriorMediaIds=new Set([...snapshot.map(item=>item.id),...fragmentBatchKnownMediaIds])}row.derivativeAltText=row.derivativeAltText||row.title;row.derivativeAttempted=true;try{return await uploadFragmentEditSource(file,row.derivativeAltText,message=>updateBatchProgress(row,message))}catch(error){recovered=await recoverBatchDerivative(row,file);if(recovered)return recovered;throw error}})();fragmentBatchDerivativeUploads.set(fingerprint,operation);try{const record=await operation;fragmentBatchKnownMediaIds.add(record.id);fragmentBatchDerivativeMediaIds.set(fingerprint,record.id);row.derivativeMediaId=record.id;return record}finally{fragmentBatchDerivativeUploads.delete(fingerprint)}}
async function runFragmentBatchRow(row){validateBatchRow(row);row.abortController=new AbortController();if(!row.masterMediaId){updateBatchRow(row,"uploading-master","Starting private master…");await uploadBatchMaster(row)}if(!row.derivativeMediaId){let derivative=row.derivativeFile||row.generatedDerivativeFile;if(!derivative&&isHeicUpload(row.masterFile)){updateBatchRow(row,"preparing-derivative","Decoding HEIC/HEIF edit source locally…");derivative=await queuedHeicEditProxy(row.masterFile);row.generatedDerivativeFile=derivative}else if(!derivative){updateBatchRow(row,"preparing-derivative","Preparing private editing source…");derivative=await derivativeFor(row.masterFile);row.generatedDerivativeFile=derivative}if(!derivative)throw new Error("Add a matching JPEG, PNG, or WebP editing source for this TIFF master.");updateBatchRow(row,"uploading-derivative","Uploading private editing source…");await uploadBatchDerivative(row,derivative)}updateBatchRow(row,"creating","Creating private draft fragment…");const fragment=await createBatchFragment(row);row.fragmentId=fragment.id;row.createAttempted=true;fragmentBatchRefreshPending=true;updateBatchRow(row,"complete","Private draft fragment created in the Fragment Library.")}
async function refreshAfterFragmentBatch(){try{await reload()}catch(error){setStatus(`Fragments uploaded, but the Blackboard list could not refresh: ${error.message}`)}}
function pumpFragmentBatch(){while(fragmentBatchRunning<BATCH_CONCURRENCY){const row=fragmentBatchRows.find(item=>item.status==="queued");if(!row)break;row.status="starting";row.message="Starting…";fragmentBatchRunning+=1;renderFragmentBatchTray();runFragmentBatchRow(row).catch(error=>{row.status="failed";row.message=error.name==="AbortError"?"Upload cancelled.":error.message}).finally(()=>{row.abortController=null;fragmentBatchRunning-=1;renderFragmentBatchTray();pumpFragmentBatch()})}if(fragmentBatchRunning===0&&!fragmentBatchRows.some(row=>row.status==="queued")){const complete=fragmentBatchRows.filter(row=>row.status==="complete").length,failed=fragmentBatchRows.filter(row=>row.status==="failed").length;fragmentBatchNotice=`${complete} fragment${complete===1?"":"s"} complete${failed?`; ${failed} need${failed===1?"s":""} attention`:""}.`;setStatus(fragmentBatchNotice);renderFragmentBatchTray();if(fragmentBatchRefreshPending){fragmentBatchRefreshPending=false;void refreshAfterFragmentBatch()}}}
function stageFragmentFiles(masters,derivatives,output){if(fragmentBatchRunning)throw new Error("Wait for the current fragment pipelines to finish before staging more files.");if(!masters.length&&!derivatives.length)throw new Error("Select or drop one or more masters or editing sources to stage.");const plan=planFragmentBatchSelection(fragmentBatchRows,fragmentBatchDerivativePool,masters,derivatives,"",BATCH_MAX_FRAGMENTS);fragmentBatchRows=plan.rows;fragmentBatchDerivativePool=plan.pool;for(const row of fragmentBatchRows)if(row.status==="failed"&&row.derivativeFile&&/editing source|derivative/i.test(row.message))row.message="Matching editing source staged. Retry from the saved checkpoint.";const notes=[];if(plan.duplicates.length)notes.push(`${plan.duplicates.length} duplicate file${plan.duplicates.length===1?" was":"s were"} ignored`);if(plan.rejected.length)notes.push(...plan.rejected);fragmentBatchNotice=notes.join(" · ")||`${masters.length} master${masters.length===1?"":"s"} and ${derivatives.length} editing source${derivatives.length===1?"":"s"} staged.`;if(output)output.textContent=fragmentBatchNotice;queueBatchPreviews();renderFragmentBatchTray()}
function updateBatchSelection(input){const output=input.closest("[data-fragment-batch-stage]")?.querySelector(`[data-batch-selection="${input.name}"]`),count=input.files.length;if(!output)return;output.textContent=count?`${count} ${input.name==="masters"?"master image":"editing source"}${count===1?"":"s"} selected`:input.name==="masters"?"No master images selected":"No editing sources selected"}
function stageFragmentBatch(form,output){const masters=[...form.elements.masters.files],derivatives=[...form.elements.derivatives.files];stageFragmentFiles(masters,derivatives,output);form.reset();updateBatchSelection(form.elements.masters);updateBatchSelection(form.elements.derivatives)}
function batchDropzone(event){return event.target instanceof Element?event.target.closest("[data-batch-dropzone]"):null}
function onBatchDragOver(event){const zone=batchDropzone(event);if(!zone)return;event.preventDefault();if(event.dataTransfer)event.dataTransfer.dropEffect="copy";zone.classList.add("is-dragover")}
function onBatchDragLeave(event){const zone=batchDropzone(event);if(zone&&!zone.contains(event.relatedTarget))zone.classList.remove("is-dragover")}
function onBatchDrop(event){const zone=batchDropzone(event);if(!zone)return;event.preventDefault();zone.classList.remove("is-dragover");const files=[...(event.dataTransfer?.files||[])],form=zone.closest("[data-fragment-batch-stage]"),output=form?.querySelector("[data-form-status]"),role=zone.dataset.batchDropzone;try{stageFragmentFiles(role==="masters"?files:[],role==="derivatives"?files:[],output);setStatus(fragmentBatchNotice)}catch(error){if(output)output.textContent=error.message;setStatus(error.message)}}

function placementValues(row){const values={};for(const input of row.querySelectorAll("[data-placement-coordinate]"))values[input.dataset.placementCoordinate]=input.value===""?null:Number(input.value);return values}
function renderPlacementBox(row){const box=row.querySelector("[data-placement-box]"),values=placementValues(row),complete=Object.values(values).every(Number.isFinite);box.hidden=!complete;if(!complete)return;box.style.left=`${values.x_percent}%`;box.style.top=`${values.y_percent}%`;box.style.width=`${values.width_percent}%`;box.style.height=`${values.height_percent}%`}
function setPlacementValues(row,values){for(const [key,value] of Object.entries(values)){const input=row.querySelector(`[data-placement-coordinate="${key}"]`);if(input)input.value=Number(value).toFixed(1)}renderPlacementBox(row)}
function placementPoint(stage,event){const rect=stage.getBoundingClientRect();return{x:Math.max(0,Math.min(100,(event.clientX-rect.left)/rect.width*100)),y:Math.max(0,Math.min(100,(event.clientY-rect.top)/rect.height*100))}}
function onPointerDown(event){const stage=event.target.closest("[data-placement-stage]");if(!stage||event.button!==0)return;event.preventDefault();const row=stage.closest("[data-placement-row]"),start=placementPoint(stage,event),enabled=row.querySelector("[data-mapping-enabled]");if(enabled)enabled.checked=true;activePlacementDrag={stage,row,start,pointerId:event.pointerId};stage.setPointerCapture?.(event.pointerId);setPlacementValues(row,{x_percent:start.x,y_percent:start.y,width_percent:.1,height_percent:.1})}
