function onInput(event){const coordinate=event.target.closest("[data-placement-coordinate]");if(coordinate){const row=coordinate.closest("[data-placement-row]"),enabled=row.querySelector("[data-mapping-enabled]");if(enabled&&coordinate.value!=="")enabled.checked=true;renderPlacementBox(row);return}const mappingToggle=event.target.closest("[data-mapping-enabled]");if(mappingToggle){const row=mappingToggle.closest("[data-placement-row]");if(!mappingToggle.checked){for(const input of row.querySelectorAll("[data-placement-coordinate]"))input.value="";renderPlacementBox(row)}return}const field=event.target.closest("[data-batch-field]");if(!field)return;const row=batchRowByElement(field);if(!row||row.status==="complete")return;row[field.dataset.batchField]=field.value;if(field.dataset.batchField==="title"&&!row.caption.trim())row.caption=field.value}
