    if(form.matches("[data-state-create]")){const body=formBody(form),pair=await uploadPair(form.elements.master.files[0],form.elements.derivative.files[0],`Complete scan of ${selected().title}`,output);body.master_media_id=pair.master.id;body.derivative_media_id=pair.derivative.id;body.occurred_at=iso(body.occurred_at);await api(endpoint(`/records/${encodeURIComponent(selectedId)}/states`),jsonOptions("POST",body));setStatus("Next Blackboard state added");return reload()}
    if(form.matches("[data-state-upload]")){const pair=await uploadPair(form.elements.master.files[0],form.elements.derivative.files[0],`Complete scan of ${selected().title}`,output);await api(endpoint(`/records/${encodeURIComponent(selectedId)}/states/${encodeURIComponent(form.dataset.stateUpload)}`),jsonOptions("POST",{master_media_id:pair.master.id,derivative_media_id:pair.derivative.id}));setStatus("State scan pair attached");return reload()}
