    if(form.matches("[data-fragment-create]")){const body=formBody(form),assets=await prepareFragmentAssets(form.elements.master.files[0],form.elements.edit_source.files[0],form.elements.title.value,output);body.master_media_id=assets.master.id;body.edit_source_media_id=assets.editSource.id;body.occurred_at=iso(body.occurred_at);body.date_precision=body.occurred_at?"exact":"undated";body.state="draft";body.public_visible=false;const payload=await fragmentRequests.create(body);activeFragmentId=payload.record.id;activeFragmentEditId="";fragmentWorkflowStep="edit";libraryView="fragments";selectedId="";setStatus("Private fragment created. Edit its image next.");return reload()}
    if(form.matches("[data-fragment-metadata]")){const body=formBody(form);body.occurred_at=iso(body.occurred_at);await fragmentRequests.patch(form.dataset.fragmentMetadata,body);setStatus("Fragment details saved");return reload()}
