    if(form.matches("[data-fragment-mappings]")){const fragment=activeFragment();if(!fragment)throw new Error("Open a fragment before saving mappings.");const existing=new Map((fragment.placements||[]).map(item=>[item.state_id||item.stateId,item])),mappings=[];for(const [index,row] of [...form.querySelectorAll("[data-placement-row]")].entries()){if(!row.querySelector("[data-mapping-enabled]")?.checked)continue;const values=placementValues(row);if(!Object.values(values).every(Number.isFinite))throw new Error("Draw or enter all four coordinates for every selected state.");const prior=existing.get(row.dataset.placementRow)||{};mappings.push({state_id:row.dataset.placementRow,x_pct:values.x_percent,y_pct:values.y_percent,width_pct:values.width_percent,height_pct:values.height_percent,hotspot_mask_media_id:prior.hotspot_mask_media_id||prior.hotspotMaskMediaId||null,hotspot_recipe:prior.hotspot_recipe||prior.hotspotRecipe||null,sort_order:index+1})}await fragmentRequests.saveMappings(fragment.id,mappings);if(output)output.textContent="State mappings saved.";setStatus("Fragment mapped to the selected Blackboard states");return reload()}
    if(form.matches("[data-state-links]")){const state_ids=[...form.querySelectorAll('[name="state_id"]:checked')].map(input=>input.value);await api(endpoint(`/records/${encodeURIComponent(selectedId)}/fragments/${encodeURIComponent(form.dataset.stateLinks)}/states`),jsonOptions("PUT",{state_ids}));setStatus("Fragment state matches saved");return reload()}
